public final class PhoneIntake {
    public interface Receiver{JSONObject receive(File file,String name)throws Exception;}
    public static JSONArray qr(File file)throws Exception{
        List<Bitmap> images=new ArrayList<>();JSONArray values=new JSONArray();Set<String> seen=new HashSet<>();
        try{if(file.getName().endsWith(".pdf")){try(PDDocument document=PDDocument.load(file)){PDFRenderer renderer=new PDFRenderer(document);for(int i=0;i<Math.min(3,document.getNumberOfPages());i++)images.add(renderer.renderImageWithDPI(i,120));}}else{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getAbsolutePath(),o);o.inSampleSize=Math.max(1,Math.max(o.outWidth,o.outHeight)/2500);o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeFile(file.getAbsolutePath(),o);if(b!=null)images.add(b);}
            try(BarcodeScanner scanner=BarcodeScanning.getClient()){for(Bitmap image:images)for(com.google.mlkit.vision.barcode.common.Barcode barcode:Tasks.await(scanner.process(InputImage.fromBitmap(image,0)),30,TimeUnit.SECONDS)){String value=barcode.getRawValue();if(value!=null&&seen.add(value))values.put(value);}}return values;
        }finally{for(Bitmap image:images)image.recycle();}
    }
    public static JSONArray mail(OptionalServices services,JSONObject args,File cache,Receiver receiver)throws Exception{
        LocalDate start=LocalDate.parse(args.getString("start")),end=LocalDate.parse(args.getString("end"));if(end.isBefore(start)||java.time.temporal.ChronoUnit.DAYS.between(start,end)>31)throw new IllegalArgumentException("请选择不超过31天的收件范围");String keyword=args.optString("keyword").trim();if(keyword.length()>100)throw new IllegalArgumentException("关键词过长");String password=services.secret("mail");Properties p=new Properties();p.setProperty("mail.store.protocol","imaps");p.setProperty("mail.imaps.peek","true");p.setProperty("mail.imaps.host","imap.163.com");p.setProperty("mail.imaps.port","993");p.setProperty("mail.imaps.ssl.checkserveridentity","true");p.setProperty("mail.imaps.connectiontimeout","20000");p.setProperty("mail.imaps.timeout","25000");p.setProperty("mail.imaps.writetimeout","25000");JSONArray out=new JSONArray();
        try(Store store=Session.getInstance(p).getStore("imaps")){store.connect("imap.163.com",services.mailAccount(),password);try(Folder folder=store.getFolder("INBOX")){folder.open(Folder.READ_ONLY);SearchTerm dates=new AndTerm(new ReceivedDateTerm(ComparisonTerm.GE,java.sql.Date.valueOf(start.toString())),new ReceivedDateTerm(ComparisonTerm.LT,java.sql.Date.valueOf(end.plusDays(1).toString())));Message[] matches=folder.search(dates);if(matches.length>200)throw new IllegalArgumentException("范围内邮件超过200封，请缩小日期范围");int[] count={0};for(Message message:matches){String subject=Objects.toString(message.getSubject(),"");if(!keyword.isEmpty()&&!subject.contains(keyword))continue;if(!subject.contains("发票")&&!subject.contains("行程"))continue;attachments(message,cache,receiver,out,count,0);}}}catch(MessagingException error){throw new IOException("邮箱连接或读取失败，请检查163授权码、IMAP开关及网络；未修改邮件");}return out;
    }
    static void attachments(Part part,File cache,Receiver receiver,JSONArray out,int[] count,int depth)throws Exception{if(depth>8)throw new IOException("邮件层级过深");if(part.isMimeType("multipart/*")){Multipart multi=(Multipart)part.getContent();for(int i=0;i<multi.getCount();i++)attachments(multi.getBodyPart(i),cache,receiver,out,count,depth+1);return;}String name=part.getFileName();if(name==null)return;name=javax.mail.internet.MimeUtility.decodeText(name);if(!name.toLowerCase(Locale.ROOT).matches(".*\\.(pdf|png|jpe?g)$"))return;if(++count[0]>50)throw new IOException("本次附件超过50份，请缩小收件范围");File temp=File.createTempFile("mail-",".part",cache);try{try(InputStream in=part.getInputStream();OutputStream dest=new FileOutputStream(temp)){copy(in,dest,20L*1024*1024);}try{out.put(receiver.receive(temp,name));}catch(Exception error){out.put(new JSONObject().put("name",name).put("error","附件读取未完成，原邮件保留"));}}finally{temp.delete();}}
    private static void copy(InputStream in,OutputStream out,long max)throws IOException{byte[] block=new byte[65536];long bytes=0;int n;while((n=in.read(block))!=-1){bytes+=n;if(bytes>max)throw new IOException("文件超过大小限制");out.write(block,0,n);}}
    private static byte[] tax(String base,String endpoint,JSONObject data,boolean get)throws Exception{
        String address=base+"/kpfw/fpjfzz/v1/"+endpoint;if(get){List<String> query=new ArrayList<>();Iterator<String> keys=data.keys();while(keys.hasNext()){String key=keys.next();query.add(URLEncoder.encode(key,"UTF-8")+"="+URLEncoder.encode(data.getString(key),"UTF-8"));}address+="?"+String.join("&",query);}HttpURLConnection connection=(HttpURLConnection)new URL(address).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(20000);connection.setReadTimeout(25000);try{if(!get){connection.setRequestMethod("POST");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/json");try(OutputStream out=connection.getOutputStream()){out.write(data.toString().getBytes(StandardCharsets.UTF_8));}}if(connection.getResponseCode()!=200)throw new IOException("税务入口未返回文件");try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){copy(in,out,20L*1024*1024);return out.toByteArray();}}finally{connection.disconnect();}}
    public static JSONObject claim(String url,File cache,Receiver receiver)throws Exception{
        URI uri;try{uri=URI.create(url);}catch(IllegalArgumentException error){throw new IllegalArgumentException("领票地址无效");}JSONObject manual=new JSONObject().put("status","manual").put("message","请在原入口领取正式PDF后导入；二维码不是发票");if(!"https".equals(uri.getScheme())||!Set.of("dppt.shanghai.chinatax.gov.cn","dppt.jiangxi.chinatax.gov.cn").contains(Objects.toString(uri.getHost(),""))||uri.getUserInfo()!=null||(uri.getPort()!=-1&&uri.getPort()!=8443)||uri.getQuery()!=null||uri.getFragment()!=null||!uri.getPath().matches("/v/[A-Za-z0-9_]{10,150}"))return manual;
        try{String base="https://"+uri.getHost()+":8443";JSONObject info=new JSONObject(new String(tax(base,"queryFpjcxxb",new JSONObject().put("Cs",uri.getPath().substring(3)),false),StandardCharsets.UTF_8));if(!info.optString("code").equals("1"))return manual;String number=info.getString("fphm");if(!number.matches("[0-9]{8,30}"))return manual;java.util.regex.Matcher qrNumber=java.util.regex.Pattern.compile("/v/[0-9]+_([0-9]{8,30})_").matcher(uri.getPath());if(qrNumber.find()&&!qrNumber.group(1).equals(number))return manual;String issued=java.time.LocalDateTime.parse(info.getString("kprq"),DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")).format(DateTimeFormatter.ofPattern("yyyyMMddHHmmss"));JSONObject params=new JSONObject().put("Fphm",number).put("Kprq",issued);JSONObject ready=new JSONObject(new String(tax(base,"queryFpmxNum",params,false),StandardCharsets.UTF_8));if(ready.has("code")&&!Set.of("1","3").contains(ready.getString("code")))return manual;params.put("Wjgs","PDF").put("Jym",info.getString("jym")).put("Czsj",String.valueOf(System.currentTimeMillis()));if(ready.has("fileName"))params.put("fileName",ready.getString("fileName"));JSONObject logged=new JSONObject(new String(tax(base,"saveDzfpxzjlxx",params,false),StandardCharsets.UTF_8));if(!logged.optString("code").equals("1"))return manual;byte[] bytes=tax(base,"exportDzfpwjEwm",params,true);if(bytes.length<5||!new String(bytes,0,5,StandardCharsets.US_ASCII).equals("%PDF-"))return manual;File temp=File.createTempFile("claimed-",".pdf",cache);try{java.nio.file.Files.write(temp.toPath(),bytes);try(PDDocument document=PDDocument.load(temp)){String text=new PDFTextStripper().getText(document);if(document.isEncrypted()||document.getNumberOfPages()==0||!number.equals(Rules.parse(text).get("invoice_number")))return manual;}return new JSONObject().put("status","received").put("entry",receiver.receive(temp,number+".pdf"));}finally{temp.delete();}}catch(Exception error){return manual;}
    }
}
